import { useEffect, useCallback } from "react";
import { useNavigate } from "react-router-dom";
import { LOGOUT_EVENT } from "../components/main/AppHeader";
import {
  deleteConversation,
  renameConversation,
  getConversation,
  listConversations,
} from "../api/chat";
import { getAuthToken } from "../api/auth";
import { parseCSV, parseXLSX } from "../utils/fileParser";
import useConversations, { INITIAL_BOT_MESSAGE } from "./useConversations";
import useDataset from "./useDataset";
import useChatMessages from "./useChatMessages";

export default function useMainPage() {
  const navigate = useNavigate();

  const {
    chats, setChats,
    activeChatId, setActiveChatId,
    activeChat,
    sidebarCollapsed, setSidebarCollapsed,
    currentConversationId, setCurrentConversationId,
  } = useConversations();

  const {
    uploaded, setUploaded,
    datasetName, setDatasetName,
    rows, setRows,
    columns, setColumns,
    uploadError, setUploadError,
    tableData, setTableData,
    tableDataBefore, setTableDataBefore,
    headers, setHeaders,
    headersBefore, setHeadersBefore,
    showPreview, setShowPreview,
    fileInputRef,
    handleUploadClick,
    resetDataset,
    restoreDatasetFromPayload,
    updateFromResponse,
    csvFileName,
    DatasetIcon,
  } = useDataset();

  const {
    isLoadingChat, setIsLoadingChat,
    chatError, setChatError,
    pendingFeedback, setPendingFeedback,
    submittingFeedback, setSubmittingFeedback,
    stepTitle, setStepTitle,
    selectedActions, setSelectedActions,
    inputValue, setInputValue,
    showHistory, setShowHistory,
    historyLogs, setHistoryLogs,
    chatEndRef,
    actions,
    cleanError,
    handleSend,
    handleAutoClean,
    handleFeedback,
    toggleAction,
    handleShowHistory: showHistoryHandler,
    canSend: _canSend,
  } = useChatMessages();

  const loadChatMessages = useCallback(
    async (conversationId) => {
      try {
        const data = await getConversation(conversationId);
        if (!data?.messages) return;

        const mapped = data.messages.length === 0
          ? [{ ...INITIAL_BOT_MESSAGE, time: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }) }]
          : data.messages.map((msg) => {
              const sender = msg.sender ?? msg.role;
              return {
                sender: sender === "user" ? "user" : "bot",
                text: msg.content,
                time: new Date(msg.created_at).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }),
                downloadUrl: msg.payload?.download_url ?? null,
              };
            });

        setChats((prev) =>
          prev.map((chat) => chat.id === conversationId ? { ...chat, messages: mapped } : chat)
        );

        const uploadMessage = data.messages.find((m) => {
          const sender = m.sender ?? m.role;
          return (sender === "assistant" || sender === "bot") && m.payload?.dataset_name;
        });
        if (uploadMessage?.payload?.dataset_name) {
          setDatasetName(uploadMessage.payload.dataset_name);
        }

        const lastAssistant = [...data.messages].reverse().find((m) => {
          const sender = m.sender ?? m.role;
          return (sender === "assistant" || sender === "bot") && m.payload;
        });

        if (lastAssistant?.payload) {
          restoreDatasetFromPayload(lastAssistant.payload);
        }
        setPendingFeedback(lastAssistant?.payload?.finished === false);
        setStepTitle(lastAssistant?.payload?.step_title ?? "");
      } catch (error) {
        console.error("Failed to load messages:", error);
        const friendly = cleanError(error.message);
        if (friendly.includes("log out")) setChatError(friendly);
      }
    },
    [restoreDatasetFromPayload, setChats, setDatasetName, setPendingFeedback, setStepTitle, cleanError, setChatError]
  );

  const loadConversations = useCallback(async () => {
    try {
      const data = await listConversations();
      if (data && data.length > 0) {
        const loadedChats = data.map((conv) => ({
          id: conv.id, title: conv.title || "Untitled Chat", messages: [], backendId: conv.id,
        }));
        setChats(loadedChats);
        setActiveChatId(loadedChats[0].id);
        setCurrentConversationId(loadedChats[0].id);
        await loadChatMessages(loadedChats[0].id);
      }
    } catch (error) {
      console.error("Failed to load conversations:", error);
      const friendly = cleanError(error.message);
      if (friendly.includes("log out")) setChatError(friendly);
    }
  }, [loadChatMessages, setChats, setActiveChatId, setCurrentConversationId, cleanError, setChatError]);

  useEffect(() => {
    if (getAuthToken()) loadConversations();
  }, [navigate, loadConversations]);

  useEffect(() => {
    const handleLogout = () => {
      resetDataset();
      setSelectedActions([]);
      setCurrentConversationId(null);
      setHistoryLogs([]);
      setChats([{ id: 1, title: "Chat 1", messages: [INITIAL_BOT_MESSAGE] }]);
      setActiveChatId(1);
    };
    window.addEventListener(LOGOUT_EVENT, handleLogout);
    return () => window.removeEventListener(LOGOUT_EVENT, handleLogout);
  }, [resetDataset, setChats, setActiveChatId, setCurrentConversationId, setSelectedActions, setHistoryLogs]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [activeChat?.messages, chatEndRef]);

  const syncConversationId = useCallback(
    (responseConvId, thisChatId) => {
      if (!currentConversationId && responseConvId) {
        setCurrentConversationId(responseConvId);
        setChats((prev) =>
          prev.map((chat) => chat.id === thisChatId ? { ...chat, id: responseConvId, backendId: responseConvId } : chat)
        );
        setActiveChatId(responseConvId);
      }
    },
    [currentConversationId, setChats, setActiveChatId, setCurrentConversationId]
  );

  const handleSwitchChat = useCallback(async (chatId) => {
    setActiveChatId(chatId);
    setCurrentConversationId(chatId);
    resetDataset();
    setPendingFeedback(false);
    await loadChatMessages(chatId);
  }, [loadChatMessages, setActiveChatId, setCurrentConversationId, resetDataset, setPendingFeedback]);

  const handleNewChat = useCallback(() => {
    const tempId = Date.now();
    setChats((prev) => [...prev, { id: tempId, title: "New Chat", messages: [{ ...INITIAL_BOT_MESSAGE, time: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }) }] }]);
    setActiveChatId(tempId);
    setCurrentConversationId(null);
    resetDataset();
    setSelectedActions([]);
    setChatError("");
    setPendingFeedback(false);
  }, [setChats, setActiveChatId, setCurrentConversationId, resetDataset, setSelectedActions, setChatError, setPendingFeedback]);

  const handleRenameChat = useCallback(async (chatId, title) => {
    const trimmedTitle = title.trim();
    if (!trimmedTitle) return;
    setChats((prev) => prev.map((chat) => chat.id === chatId ? { ...chat, title: trimmedTitle } : chat));
    if (typeof chatId === "string") {
      try {
        await renameConversation(chatId, trimmedTitle);
      } catch (error) {
        console.error("Failed to rename conversation:", error);
        const message = error?.message || "Could not rename conversation";
        setChatError(message);
        if (/token|unauthorized|expired|invalid/i.test(message)) navigate("/login");
      }
    }
  }, [setChats, navigate, setChatError]);

  const handleDeleteChat = useCallback(async (chatId) => {
    const remaining = chats.filter((c) => c.id !== chatId);
    setChats(remaining);
    if (activeChatId === chatId) {
      if (remaining.length > 0) await handleSwitchChat(remaining[0].id);
      else handleNewChat();
    }
    try { await deleteConversation(chatId); } catch (error) { console.error("Failed to delete conversation:", error); }
  }, [chats, activeChatId, handleSwitchChat, handleNewChat, setChats]);

  const handleFileUpload = async (event) => {
    const selectedFile = event.target.files?.[0];
    if (!selectedFile) return;

    const fileName = selectedFile.name.toLowerCase();
    const isCSV = fileName.endsWith(".csv");
    const isXLSX = fileName.endsWith(".xlsx") || fileName.endsWith(".xls");

    if (!isCSV && !isXLSX) {
      setUploadError(`"${selectedFile.name}" is not supported. Please upload a CSV, or Excel file.`);
      event.target.value = "";
      return;
    }
    if (selectedFile.type && !["text/csv", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", "application/vnd.ms-excel"].includes(selectedFile.type)) {
      setUploadError(`"${selectedFile.name}" appears to be an image or unsupported file. Please upload a CSV, or Excel file.`);
      event.target.value = "";
      return;
    }

    const thisChatId = activeChatId;
    const thisConvId = currentConversationId;

    setIsLoadingChat(true);
    setChatError("");

    try {
      const parsed = isCSV ? parseCSV(await selectedFile.text()) : await parseXLSX(selectedFile);

      setDatasetName(selectedFile.name);
      setRows(parsed.rows);
      setColumns(parsed.columns);
      setTableData(parsed.data);
      setHeaders(parsed.headers);
      setHeadersBefore(parsed.headers);
      setUploadError("");
      setUploaded(true);

      const response = await sendChatMessage({
        message: `I've uploaded a dataset: ${selectedFile.name}. It has ${parsed.rows} rows and ${parsed.columns} columns.`,
        mode: "chat",
        selectedIntents: [],
        conversationId: thisConvId,
        dataset: selectedFile,
      });

      const realConvId = response.conversation_id ?? thisConvId;
      syncConversationId(response.conversation_id, thisChatId);

      const time = new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
      setChats((prev) =>
        prev.map((chat) =>
          chat.id === thisChatId || chat.id === realConvId
            ? { ...chat, messages: [...chat.messages, { sender: "user", text: `I've uploaded a dataset: ${selectedFile.name}. It has ${parsed.rows} rows and ${parsed.columns} columns.`, time }, { sender: "bot", text: response.assistant_message || `✓ Dataset loaded: ${selectedFile.name}`, time, downloadUrl: response.result?.download_url ?? null }] }
            : chat
        )
      );
    } catch (error) {
      console.error("File upload error:", error);
      setChatError(cleanError(error.message));
      setUploadError(cleanError(error.message));
    } finally {
      setIsLoadingChat(false);
      event.target.value = "";
    }
  };

  const handleReset = () => {
    if (!window.confirm('Are you sure you want to reset all uploaded data? This action cannot be undone.')) return;
    resetDataset();
    setSelectedActions([]);
  };

  const handleDownload = () => {
    const lastWithDownload = activeChat.messages.slice().reverse().find((m) => m.downloadUrl);
    if (!lastWithDownload) { console.error("No download URL found"); return; }
    window.open(lastWithDownload.downloadUrl, "_blank");
  };

  const onSend = () => handleSend({
    activeChatId, currentConversationId, headers, tableData, csvFileName, setChats, syncConversationId, updateFromResponse,
  });

  const onAutoClean = () => handleAutoClean({
    uploaded, headers, tableData, csvFileName, activeChatId, currentConversationId,
    isLoadingChat, pendingFeedback, setChats, syncConversationId, updateFromResponse,
  });

  const onFeedback = (accept) => handleFeedback({
    currentConversationId, submittingFeedback, setChats, updateFromResponse,
  });

  const onShowHistory = () => showHistoryHandler(currentConversationId);

  const canSend = _canSend(uploaded, inputValue, selectedActions);
  const autoCleanDisabled = !uploaded || isLoadingChat || pendingFeedback;

  return {
    uploaded, datasetName, rows, columns, uploadError,
    tableData, tableDataBefore, headers, headersBefore,
    showPreview, setShowPreview,
    selectedActions, inputValue, setInputValue,
    showHistory, setShowHistory, historyLogs,
    isLoadingChat, chatError, pendingFeedback, submittingFeedback, stepTitle,
    fileInputRef, chatEndRef,
    actions, chats, activeChatId, sidebarCollapsed, setSidebarCollapsed, activeChat,
    handleNewChat, handleSwitchChat, handleRenameChat, handleDeleteChat,
    handleUploadClick, handleFileUpload, handleReset, handleDownload,
    onShowHistory, onAutoClean, onSend, onFeedback, toggleAction,
    DatasetIcon, canSend, autoCleanDisabled,
  };
}
